public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    String S = sc.next();
    String T = sc.next();
    String ans = "No";
    int n = 0;
    int limit = 3;

    if (T.charAt(2) == 'X') {
        limit = 2;
    }

    for (int i = 0; i < S.length(); i++) {
        char chS = S.charAt(i);
        int numS = chS - 'a';

        if (n < T.length()) {
            char chT = T.charAt(n);
            int numT = chT - 'A';

            if (numS == numT) {
                n++;
            }
        }

        if (n >= limit) {
            ans = "Yes";
            break;
        }
    }

    System.out.println(ans);
    sc.close();
}
